// Pure domain logic for bookmarks. No I/O here so it can be unit-tested and
// reused by the HTTP layer. Behaviour is derived from the approved scenarios
// SCN-001..SCN-008 (see context/scenarios).

/**
 * Normalise a raw user-entered link into a canonical URL string, or return
 * null when the text cannot be interpreted as a web address (SCN-005: invalid
 * input is rejected).
 */
function normaliseUrl(raw) {
  if (typeof raw !== 'string') return null;
  let v = raw.trim();
  if (!v) return null;
  if (!/^https?:\/\//i.test(v)) v = 'https://' + v;
  let u;
  try {
    u = new URL(v);
  } catch (e) {
    return null;
  }
  // A usable web address must have a host with a dot or be localhost.
  if (!u.hostname || (u.hostname.indexOf('.') === -1 && u.hostname !== 'localhost')) {
    return null;
  }
  // Canonical form used for storage and duplicate detection.
  u.hash = '';
  return u.toString();
}

/** Normalise a tag: trimmed, lower-cased (SCN-002). Returns '' if empty. */
function normaliseTag(raw) {
  if (typeof raw !== 'string') return '';
  return raw.trim().toLowerCase();
}

/**
 * Find an existing bookmark with the same canonical URL (SCN-006: duplicate
 * detection by same web address).
 */
function findDuplicate(bookmarks, url) {
  return bookmarks.find((b) => b.url === url) || null;
}

/** The friendly host label shown in the UI. */
function hostLabel(url) {
  try {
    return new URL(url).hostname.replace(/^www\./, '');
  } catch (e) {
    return '';
  }
}

/**
 * Filter bookmarks for display given the current view, search text and tag
 * filter (SCN-003 search/tag filter, SCN-004 read-later views).
 * view: 'all' | 'unread' | 'read'
 */
function filterBookmarks(bookmarks, { view = 'all', search = '', tag = null } = {}) {
  const q = (search || '').trim().toLowerCase();
  const tagFilter = tag ? normaliseTag(tag) : null;
  return bookmarks.filter((b) => {
    if (view === 'unread' && !(b.readLater && !b.read)) return false;
    if (view === 'read' && !(b.readLater && b.read)) return false;
    if (tagFilter && !b.tags.includes(tagFilter)) return false;
    if (!q) return true;
    const hay = (b.title + ' ' + b.url + ' ' + b.tags.join(' ')).toLowerCase();
    return hay.indexOf(q) !== -1;
  });
}

/** Count of read-later bookmarks still unread (the "To read" badge, SCN-004). */
function unreadCount(bookmarks) {
  return bookmarks.filter((b) => b.readLater && !b.read).length;
}

/** All distinct tags in use, sorted — for the as-you-type suggestions (SCN-002). */
function allTags(bookmarks) {
  const set = new Set();
  bookmarks.forEach((b) => b.tags.forEach((t) => set.add(t)));
  return Array.from(set).sort();
}

module.exports = {
  normaliseUrl,
  normaliseTag,
  findDuplicate,
  hostLabel,
  filterBookmarks,
  unreadCount,
  allTags,
};
'use strict';

const path = require('path');
const express = require('express');
const logic = require('./logic');
const { fetchTitle: realFetchTitle } = require('./titleFetcher');

/**
 * Build the Express app. Dependencies are injected so tests can supply an
 * in-memory store and a stub title fetcher.
 *
 * @param {object} opts
 * @param {{load:Function, save:Function}} opts.store
 * @param {Function} [opts.fetchTitle] async (url) => { ok, title }
 */
function createApp({ store, fetchTitle = realFetchTitle }) {
  const app = express();
  app.use(express.json());
  app.use(express.static(path.join(__dirname, '..', 'public')));

  // In-memory working state, persisted through the store on every change.
  const state = store.load();

  function persist() {
    store.save(state);
  }

  function publicBookmark(b) {
    return {
      id: b.id,
      url: b.url,
      title: b.title,
      titleFailed: !!b.titleFailed,
      tags: b.tags.slice(),
      readLater: !!b.readLater,
      read: !!b.read,
      host: logic.hostLabel(b.url),
      createdAt: b.createdAt,
    };
  }

  function snapshot() {
    return {
      bookmarks: state.bookmarks.map(publicBookmark),
      allTags: logic.allTags(state.bookmarks),
      unreadCount: logic.unreadCount(state.bookmarks),
      total: state.bookmarks.length,
    };
  }

  // List everything the UI needs; filtering/searching happens in the client
  // (SCN-003/004) but is also covered by unit tests on logic.filterBookmarks.
  app.get('/api/bookmarks', (req, res) => {
    res.json(snapshot());
  });

  // Save a new link (SCN-001, SCN-005 invalid, SCN-006 duplicate).
  app.post('/api/bookmarks', async (req, res) => {
    const url = logic.normaliseUrl(req.body && req.body.url);
    if (!url) {
      return res.status(400).json({ error: 'invalid_url' });
    }
    const existing = logic.findDuplicate(state.bookmarks, url);
    if (existing) {
      return res.status(409).json({ duplicate: true, bookmark: publicBookmark(existing) });
    }
    let title = url;
    let titleFailed = false;
    try {
      const result = await fetchTitle(url);
      if (result && result.ok && result.title) {
        title = result.title;
      } else {
        titleFailed = true;
      }
    } catch (e) {
      titleFailed = true;
    }
    const bookmark = {
      id: state.nextId++,
      url,
      title,
      titleFailed,
      tags: [],
      readLater: !!(req.body && req.body.readLater),
      read: false,
      createdAt: new Date().toISOString(),
    };
    state.bookmarks.unshift(bookmark); // newest first (SCN-001)
    persist();
    res.status(201).json({ bookmark: publicBookmark(bookmark) });
  });

  // Update a bookmark: rename, tags, read-later membership, read status
  // (SCN-001 rename, SCN-002 tags, SCN-004 read-later/read).
  app.patch('/api/bookmarks/:id', (req, res) => {
    const id = Number(req.params.id);
    const b = state.bookmarks.find((x) => x.id === id);
    if (!b) return res.status(404).json({ error: 'not_found' });
    const body = req.body || {};

    if (typeof body.title === 'string') {
      const t = body.title.trim();
      if (t) {
        b.title = t;
        b.titleFailed = false; // client provided a real name
      }
    }
    if (Array.isArray(body.tags)) {
      const seen = [];
      body.tags.forEach((raw) => {
        const t = logic.normaliseTag(raw);
        if (t && !seen.includes(t)) seen.push(t);
      });
      b.tags = seen;
    }
    if (typeof body.readLater === 'boolean') {
      b.readLater = body.readLater;
      if (!b.readLater) b.read = false; // leaving read-later clears read status
    }
    if (typeof body.read === 'boolean') {
      // Read status only meaningful for read-later items.
      b.read = b.readLater ? body.read : false;
    }
    persist();
    res.json({ bookmark: publicBookmark(b) });
  });

  // Delete a bookmark permanently (SCN-007). Confirmation happens in the UI.
  app.delete('/api/bookmarks/:id', (req, res) => {
    const id = Number(req.params.id);
    const idx = state.bookmarks.findIndex((x) => x.id === id);
    if (idx === -1) return res.status(404).json({ error: 'not_found' });
    state.bookmarks.splice(idx, 1);
    persist();
    res.status(204).end();
  });

  return app;
}

module.exports = { createApp };
