const fs = require('fs');
const path = require('path');

// Simple file-backed store so bookmarks persist across sessions (SCN-008).
// One JSON document holding an array of bookmarks plus the id counter. Writes
// are atomic (write temp then rename) to avoid corruption on crash.

function createStore(filePath) {
  const dir = path.dirname(filePath);

  function load() {
    try {
      const txt = fs.readFileSync(filePath, 'utf8');
      const data = JSON.parse(txt);
      if (!data || !Array.isArray(data.bookmarks)) {
        return { bookmarks: [], nextId: 1 };
      }
      return { bookmarks: data.bookmarks, nextId: data.nextId || 1 };
    } catch (e) {
      // Missing or unreadable file -> start empty.
      return { bookmarks: [], nextId: 1 };
    }
  }

  function save(state) {
    fs.mkdirSync(dir, { recursive: true });
    const tmp = filePath + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(state, null, 2), 'utf8');
    fs.renameSync(tmp, filePath);
  }

  return { load, save };
}

module.exports = { createStore };
'use strict';

// Fetches the real page title for a URL (SCN-001). On any failure it resolves
// with { ok: false } so the caller can fall back to showing the address
// (SCN-005: a failed title fetch never blocks saving).

function decodeEntities(s) {
  return s
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(parseInt(n, 10)));
}

function extractTitle(html) {
  const m = /<title[^>]*>([\s\S]*?)<\/title>/i.exec(html);
  if (!m) return null;
  const t = decodeEntities(m[1]).replace(/\s+/g, ' ').trim();
  return t || null;
}

async function fetchTitle(url, { timeoutMs = 8000, fetchImpl = globalThis.fetch } = {}) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const res = await fetchImpl(url, {
      signal: controller.signal,
      redirect: 'follow',
      headers: { 'User-Agent': 'BookmarksApp/1.0 (+title-fetch)' },
    });
    if (!res.ok) return { ok: false };
    const ctype = res.headers.get('content-type') || '';
    if (ctype && !/text\/html|application\/xhtml/i.test(ctype)) return { ok: false };
    const html = await res.text();
    const title = extractTitle(html);
    if (!title) return { ok: false };
    return { ok: true, title };
  } catch (e) {
    return { ok: false };
  } finally {
    clearTimeout(timer);
  }
}

module.exports = { fetchTitle, extractTitle, decodeEntities };
